func (r *ApplicationDataSourceModel) ToOperationsAutomationGetApplicationRequest(ctx context.Context) (*operations.AutomationGetApplicationRequest, diag.Diagnostics) {
	var diags diag.Diagnostics

	organizationID := new(string)
	if !r.OrganizationID.IsUnknown() && !r.OrganizationID.IsNull() {
		*organizationID = r.OrganizationID.ValueString()
	} else {
		organizationID = nil
	}
	environmentID := new(string)
	if !r.EnvironmentID.IsUnknown() && !r.EnvironmentID.IsNull() {
		*environmentID = r.EnvironmentID.ValueString()
	} else {
		environmentID = nil
	}
	var domainKey string
	domainKey = r.DomainKey.ValueString()

	var key string
	key = r.Key.ValueString()

	out := operations.AutomationGetApplicationRequest{
		OrganizationID: organizationID,
		EnvironmentID:  environmentID,
		DomainKey:      domainKey,
		Key:            key,
	}

	return &out, diags
}
